 "content": "def transform(grid):
    # Each hollow frame is a stencil. Copy the pattern inside the irregular
    # reference frame (the one with a nonuniform interior) into the other frames.
    h, w = len(grid), len(grid[0])
    # Locate colored rectangular frames by their bounding boxes.
    colors = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                colors.setdefault(v, []).append((r,c))
    boxes = {}
    for v, pts in colors.items():
        boxes[v] = (min(r for r,c in pts), max(r for r,c in pts), min(c for r,c in pts), max(c for r,c in pts))
    # Identify the pattern by finding its bounding frame and interior mask.
    # Pattern object has a complete border plus nonzero interior marks.
    source = None
    for v,(r0,r1,c0,c1) in boxes.items():
        if r1-r0 < 2 or c1-c0 < 2: continue
        inside = [(r,c) for r,c in colors[v] if r0<r<r1 and c0<c<c1]
        if inside:
            source=(v,r0,r1,c0,c1)
            break
    if source is None: return grid
    sv,r0,r1,c0,c1=source
    pattern={(r-r0,c-c0) for r,c in colors[sv] if r0<r<r1 and c0<c<c1}
    out=[row[:] for row in grid]
    # Other frames receive the interior pattern, replacing their empty interior.
    for v,(a,b,x,y) in boxes.items():
        if v==sv or b-a != r1-r0 or y-x != c1-c0: continue
        for r in range(a+1,b):
            for c in range(x+1,y): out[r][c]=0
        for dr,dc in pattern:
            out[a+dr][x+dc]=v
    return out
